DIALOGS = [
[trp_sod_strategy_advisor, "sa_select_melee_cavalry", [
		(try_begin),
			(eq, "$g_sod_sa_talk_subject", 11),
			(str_store_string, s1, "@In my opinion, the Swadian cavalry can go head to toe with the Adenians if you allow them to amass enough horses.  All of their cavalry must first serve as infantry so by the time they reach the rank of Man-at-Arms and then Knight, they are very skilled in hand to hand combat. The kingdom of Swadia is surrounded by enemies and yet they still remain.  The Swadian army is composed of many different army branches with no obvious weaknesses.  Their army is versatile and their cavalry is fast enough to allow them to defend all borders.  You will need to separate their army and outthink them."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 12),
			(str_store_string, s1, "@Nothing to spectacular about the Vaegir cavalry but they fill their role nicely.  They range in rank from Horseman to Knight but I guess I should throw in Veterans as well.  They can sometimes be seen riding horses or fighting from foot."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 13),
			(str_store_string, s1, "@Tribesmen, Skirmishers, Horsemen, and Lancers are all technically melee cavalry but beware, even these soldiers will pull out a bow from time to time."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 14),
			(str_store_string, s1, "@The Nords do not fight on horseback.  Perhaps this is why they are close allies with the Jotnar Clan.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 15),
			(str_store_string, s1, "@The Rhodoks do not fight on horseback.  Perhaps this is why they are close allies with the Serpent Host.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 21),
			(str_store_string, s1, "@The melee cavalry consists of mostly Scouts but some do rise to the ranks of Cavalry.  Antarians do not heavily depend on cavalry but they are essential for flanking archers and crossbowmen that could decimate an Antarian force before they reach their target. A resourceful leader will use all tools available.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 22),
			(str_store_string, s1, "@The Marinarians do not depend on melee cavalry.  They have a small scout force used for reconnaissance, but depend on their spears for anti-cavalry and bolts for anti-infantry."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 23),
			(str_store_string, s1, "@The bread and butter of the Adenian army.  Their structure is easily described as Light, Medium, and Heavy cavalry.  Only Swadian knights can compare to the strength of these riders."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 24),
			(str_store_string, s1, "@The Villianese spend too much of their time training archers and their cavalry is weak and ineffective.  They have a small scout force used for reconnaissance and the occasional village raid. "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 37),
			(str_store_string, s1, "@The Boar Clan melee cavalry branch of their army consists of Riders and Veteran Riders.  Instead of horses, they ride camels into battle.  In my opinion, this is a waste of a perfectly good troop.  Camels are slow and cannot be turned as quickly as a horse.  Sure they are strong and semi-intelligent when it comes to survival, but a mount is replaceable.  Why would a warrior want to ride a mount that is so concerned about self preservation?  But do not let me give you a bad impression, they are strong units that are well equipped and experienced.  But having served in the cavalry myself for so long, I just feel there is some wasted potential."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 25),
			(str_store_string, s1, "@The Zerrikanians are known for their ability to tame wild horses and decorate their steeds in battle.  Their melee cavalry consists of Scouts, Harvesters, and Reapers.  They are named for their ability to quickly strike an enemy camp and rather than kill, haul away the victims. Even though I classify them as melee cavalry, many of these units will employ ranged weaponry if they cannot reach you by hand, including throwing balanced hammers."),
		(try_end),
	], "{s1}", "sa_select_3", []],
]
